182:    public void testSleepEntryAndWakeUpForProcessing() throws Exception {
183:        final long processingTimeMs = 3000;
184:        final int wakeupTime = 100;
185:        initTest(processingTimeMs, wakeupTime);
186:        assertTrue(mDisplayInterface.waitForDisplayStateChange(WAIT_TIMEOUT_MS));
187:
188:        mPowerHal.setCurrentPowerState(new PowerState(PowerHalService.STATE_SHUTDOWN_PREPARE,
189:                PowerHalService.SHUTDOWN_CAN_SLEEP));
190:        mPowerEventProcessingHandler.waitForPrepareShutdown(WAIT_TIMEOUT_MS);
191:        assertFalse(mDisplayInterface.waitForDisplayStateChange(WAIT_TIMEOUT_MS));
192:        assertStateReceivedForShutdownOrSleepWithPostpone(PowerHalService.SET_DEEP_SLEEP_ENTRY,
193:                WAIT_TIMEOUT_LONG_MS, 0);
194:        mPowerEventListener.waitForSleepEntry(WAIT_TIMEOUT_MS);
195:        mSystemStateInterface.setWakeupCausedByTimer(true);
196:        int wakeupTimeReceived = mSystemStateInterface.waitForSleepEntryAndWakeup(WAIT_TIMEOUT_MS);
197:        assertEquals(wakeupTime, wakeupTimeReceived);
198:        assertStateReceived(PowerHalService.SET_DEEP_SLEEP_EXIT, 0);
199:        mPowerEventListener.waitForSleepExit(WAIT_TIMEOUT_MS);
200:        // second processing after wakeup
201:        assertFalse(mDisplayInterface.getDisplayState());
202:        mPowerEventProcessingHandler.waitForPrepareShutdown(WAIT_TIMEOUT_MS);
203:        assertStateReceivedForShutdownOrSleepWithPostpone(PowerHalService.SET_DEEP_SLEEP_ENTRY,
204:                WAIT_TIMEOUT_LONG_MS, 0);
205:        mPowerEventListener.waitForSleepEntry(WAIT_TIMEOUT_MS);
206:        // PM will shutdown system as it was not woken-up due to timer and it is not power on.
207:        mSystemStateInterface.setWakeupCausedByTimer(false);
208:        wakeupTimeReceived = mSystemStateInterface.waitForSleepEntryAndWakeup(WAIT_TIMEOUT_MS);
209:        assertEquals(wakeupTime, wakeupTimeReceived);
210:        assertStateReceived(PowerHalService.SET_DEEP_SLEEP_EXIT, 0);
211:        assertStateReceived(PowerHalService.SET_SHUTDOWN_START, wakeupTime);
212:        mPowerEventListener.waitForShutdown(WAIT_TIMEOUT_MS);
213:        mSystemStateInterface.waitForShutdown(WAIT_TIMEOUT_MS);
214:        assertFalse(mDisplayInterface.getDisplayState());
215:    }
