217:    private void assertStateReceived(int expectedState, int expectedParam) throws Exception {
218:        int[] state = mPowerHal.waitForSend(WAIT_TIMEOUT_MS);
219:        assertEquals(expectedState, state[0]);
220:        assertEquals(expectedParam, state[1]);
221:    }
222:
223:    private void assertStateReceivedForShutdownOrSleepWithPostpone(int lastState, long timeoutMs,
224:            int expectedParamForShutdown) throws Exception {
225:        while (true) {
226:            int[] state = mPowerHal.waitForSend(timeoutMs);
227:            if (state[0] == PowerHalService.SET_SHUTDOWN_POSTPONE) {
228:                continue;
229:            }
230:            if (state[0] == lastState) {
231:                assertEquals(expectedParamForShutdown, state[1]);
232:                return;
233:            }
234:        }
235:    }
