237:    private static void waitForSemaphore(Semaphore semaphore, long timeoutMs)
238:            throws InterruptedException {
239:        if (!semaphore.tryAcquire(timeoutMs, TimeUnit.MILLISECONDS)) {
240:            throw new IllegalStateException("timeout");
241:        }
242:    }
