33:
34:import org.junit.Assert;
35:import org.junit.Test;
36:import org.junit.runner.RunWith;
37:
38:import java.io.File;
39:import java.time.Duration;
40:import java.util.Set;
41:
42:
43:/**
44: * The test suite will execute end-to-end Car HVAC API test by generating HVAC property data from
45: * default VHAL and verify those data on the fly. The test data is coming from assets/ folder in the
46: * test APK and will be shared with VHAL to execute the test.
47: */
48:@RunWith(AndroidJUnit4.class)
49:@LargeTest
50:public class CarHvacTest extends E2eCarTestBase {
51:    private static final String TAG = Utils.concatTag(CarHvacTest.class);
52:
53:    // Test should be completed within 1 hour as it only covers a finite set of HVAC properties
54:    private static final Duration TEST_TIME_OUT = Duration.ofHours(1);
55:
56:    private static final String CAR_HVAC_TEST_JSON = "car_hvac_test.json";
57:
58:    // Referred to hardware/interfaces/automotive/vehicle/2.0/types.hal, some of the HVAC properties
59:    // are in CONTINUOUS mode. They should be omitted when testing ON_CHANGE properties.
60:    private static final Set<Integer> CONTINUOUS_HVAC_PROPS;
61:
62:    private Integer mNumPropEventsToSkip;
63:
64:    static {
65:        CONTINUOUS_HVAC_PROPS = new ArraySet<>();
66:        CONTINUOUS_HVAC_PROPS.add(VehicleProperty.ENV_OUTSIDE_TEMPERATURE);
67:    }
68:
69:
70:    private class CarHvacOnChangeEventListener implements CarHvacEventCallback {
71:        private VhalEventVerifier mVerifier;
72:
73:        CarHvacOnChangeEventListener(VhalEventVerifier verifier) {
74:            mVerifier = verifier;
75:        }
76:
77:        @Override
78:        public void onChangeEvent(CarPropertyValue carPropertyValue) {
79:            VehiclePropValue event = Utils.fromHvacPropertyValue(carPropertyValue);
80:            if (!CONTINUOUS_HVAC_PROPS.contains(event.prop)) {
81:                synchronized (mNumPropEventsToSkip) {
82:                    if (mNumPropEventsToSkip == 0) {
83:                        mVerifier.verify(Utils.fromHvacPropertyValue(carPropertyValue));
84:                    } else {
85:                        mNumPropEventsToSkip--;
86:                    }
87:                }
88:            }
89:        }
90:
91:        @Override
92:        public void onErrorEvent(final int propertyId, final int zone) {
93:            Assert.fail("Error: propertyId=" + toHexString(propertyId) + " zone=" + zone);
94:        }
95:    }
96:
97:    private Integer calculateNumPropEventsToSkip(CarHvacManager hvacMgr) {
98:        int numToSkip = 0;
99:        try {
100:            for (CarPropertyConfig c: hvacMgr.getPropertyList()) {
101:                if (!CONTINUOUS_HVAC_PROPS.contains(c.getPropertyId())) {
102:                    numToSkip += c.getAreaCount();
103:                }
104:            }
105:        } catch (Exception e) {
106:            Log.d(TAG, "Unhandled exception thrown: ", e);
107:        }
108:        return Integer.valueOf(numToSkip);
109:    }
110:    @Test
111:    public void testHvacOperations() throws Exception {
112:        Log.d(TAG, "Prepare HVAC test data");
113:        VhalEventVerifier verifier = new VhalEventVerifier(getExpectedEvents(CAR_HVAC_TEST_JSON));
114:        File sharedJson = makeShareable(CAR_HVAC_TEST_JSON);
115:
116:        Log.d(TAG, "Start listening to the HAL");
117:        CarHvacManager hvacMgr = (CarHvacManager) mCar.getCarManager(Car.HVAC_SERVICE);
118:        // Calculate number of properties to skip due to registration event
119:        mNumPropEventsToSkip = calculateNumPropEventsToSkip(hvacMgr);
120:        CarHvacEventCallback callback = new CarHvacOnChangeEventListener(verifier);
121:        hvacMgr.registerCallback(callback);
122:
123:        Log.d(TAG, "Send command to VHAL to start generation");
124:        VhalEventGenerator hvacGenerator =
125:                new JsonVhalEventGenerator(mVehicle).setJsonFile(sharedJson);
126:        hvacGenerator.start();
127:
128:        Log.d(TAG, "Receiving and verifying VHAL events");
129:        verifier.waitForEnd(TEST_TIME_OUT.toMillis());
130:
131:        Log.d(TAG, "Send command to VHAL to stop generation");
132:        hvacGenerator.stop();
133:        hvacMgr.unregisterCallback(callback);
134:
135:        assertTrue("Detected mismatched events: " + verifier.getResultString(),
136:                    verifier.getMismatchedEvents().isEmpty());
137:    }
138:}

